#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using i128 = __int128_t;

const int MOD = 998244353;

string to_string(i128 x) {
    if (x == 0) return "0";
    string s;
    bool neg = x < 0;
    if (neg) x = -x;
    while (x > 0) {
        s.push_back('0' + (x % 10));
        x /= 10;
    }
    if (neg) s.push_back('-');
    reverse(s.begin(), s.end());
    return s;
}

void meet_in_middle(const vector<int>& a, int b, i128& res) {
    int n = a.size();
    vector<int> L, R;

    for (int mask = 0; mask < (1 << (n/2)); ++mask) {
        int sum = b;
        for (int i = 0; i < n/2; ++i) {
            if (mask & (1 << i)) {
                sum = (sum + a[i]) % MOD;
            }
        }
        L.push_back(sum);
    }

    for (int mask = 0; mask < (1 << (n - n/2)); ++mask) {
        int sum = 0;
        for (int i = 0; i < n - n/2; ++i) {
            if (mask & (1 << i)) {
                sum = (sum + a[n/2 + i]) % MOD;
            }
        }
        R.push_back(sum);
    }

    sort(L.begin(), L.end());
    sort(R.begin(), R.end());

    ll sumR = 0;
    for (int x : R) sumR = (sumR + x) % MOD;

    int j = R.size() - 1;
    for (int x : L) {
        while (j >= 0 && x + R[j] >= MOD) --j;
        res += (ll)x * R.size() + sumR - (ll)(R.size() - 1 - j) * MOD;
    }
}

ll pow10[17];

ll count_numbers_with_prefix(const string& pre, ll max_n, const string& nstr) {
    ll val = 0;
    for (char c : pre) val = val * 10 + (c - '0');

    ll cnt = 0;
    int plen = pre.size();
    int nlen = nstr.size();

    for (int len = plen; len <= nlen; ++len) {
        if (len < nlen) {
            cnt += pow10[len - plen];
        } else {
            if (pre < nstr) {
                cnt += pow10[len - plen];
            } else if (pre == nstr) {
                cnt += max_n - val * pow10[nlen - plen] + 1;
            }
        }
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    string ns;
    if (n == 0) ns = "0";
    else {
        ll t = n;
        while (t) {
            ns.push_back('0' + (t % 10));
            t /= 10;
        }
        reverse(ns.begin(), ns.end());
    }

    pow10[0] = 1;
    for (int i = 1; i < 17; ++i) pow10[i] = pow10[i-1] * 10;

    i128 ans = 0;

    for (int num_len = 1; num_len <= (int)ns.size(); ++num_len) {
        for (int diff_pos = 0; diff_pos < min(num_len, (int)ns.size()); ++diff_pos) {
            string cur_prefix;
            ll cur_val = 0;

            for (int i = 0; i < diff_pos; ++i) {
                cur_prefix.push_back(ns[i]);
                cur_val = cur_val * 10 + (ns[i] - '0');
            }

            for (int d = 0; d <= 9; ++d) {
                if (diff_pos == 0 && d == 0) continue;
                if (diff_pos < (int)ns.size() && d == ns[diff_pos] - '0') continue;
                if (num_len == (int)ns.size() && d > ns[diff_pos] - '0') continue;

                string new_prefix = cur_prefix + char('0' + d);
                ll new_val = cur_val * 10 + d;

                ll base_count = 0;
                string tmp;

                for (int i = 0; i < (int)new_prefix.size(); ++i) {
                    char start_digit = (i == 0) ? '1' : '0';
                    for (char c = start_digit; c < new_prefix[i]; ++c) {
                        base_count += count_numbers_with_prefix(tmp + c, n, ns);
                    }
                    tmp.push_back(new_prefix[i]);
                }
                base_count += (int)new_prefix.size() - 1;

                vector<int> coeffs;
                tmp = new_prefix;
                for (int i = new_prefix.size(); i < num_len; ++i) {
                    int cnt = count_numbers_with_prefix(tmp + '0', n, ns) % MOD;
                    coeffs.push_back(cnt);
                    tmp.push_back('0');
                }

                base_count += 1;
                base_count -= new_val * pow10[num_len - new_prefix.size()];

                for (int i = 0; i < (int)coeffs.size(); ++i) {
                    coeffs[(int)coeffs.size() - 1 - i] -= pow10[i] % MOD;
                }

                int b = base_count % MOD;
                if (b < 0) b += MOD;

                for (int& c : coeffs) {
                    c %= MOD;
                    if (c < 0) c += MOD;
                }

                meet_in_middle(coeffs, b, ans);
            }
        }
    }

    // Handle exact prefixes
    string prefix;
    ll val = 0;
    for (int len = 1; len <= (int)ns.size(); ++len) {
        prefix.push_back(ns[len-1]);
        val = val * 10 + (ns[len-1] - '0');

        ll cnt = 1;
        string tmp;
        for (int i = 0; i < (int)prefix.size(); ++i) {
            char start_digit = (i == 0) ? '1' : '0';
            for (char c = start_digit; c < prefix[i]; ++c) {
                cnt += count_numbers_with_prefix(tmp + c, n, ns);
            }
            tmp.push_back(prefix[i]);
        }
        cnt += (int)prefix.size() - 1;
        cnt -= val;
        cnt %= MOD;
        if (cnt < 0) cnt += MOD;

        ans += cnt;
    }

    ans %= 1000000007LL;
    cout << to_string(ans) << "\n";

    return 0;
}
